```java
import java.util.Scanner;

/**
 * Solução para o problema de ordenação de placas de carro usando Radix Sort.
 * A ordenação é feita com base nos quatro dígitos numéricos da placa,
 * de forma estável e em tempo linear.
 */
class Solution {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        // Lê a linha de entrada e verifica se não está vazia
        if (!in.hasNextLine()) {
            System.out.println("");
            in.close();
            return;
        }

        String entrada = in.nextLine();
        if (entrada == null || entrada.trim().isEmpty()) {
            System.out.println("");
            in.close();
            return;
        }

        String[] placas = entrada.split(",");

        // Aplica o Radix Sort nos dígitos numéricos da placa.
        // A parte numérica está nos índices 4, 5, 6 e 7.
        // O Radix Sort começa pelo dígito menos significativo (índice 7).
        final int ultimoIndiceNumerico = 7;
        final int primeiroIndiceNumerico = 4;

        for (int i = ultimoIndiceNumerico; i >= primeiroIndiceNumerico; i--) {
            placas = countingSortPorDigito(placas, i);
        }

        // Formata a saída usando String.join para evitar erros com vírgulas/espaços extras.
        String saida = String.join(", ", placas);
        System.out.println(saida);

        in.close();
    }

    /**
     * Ordena o array de placas com base no dígito na posição 'digitIndex'.
     * Utiliza o algoritmo Counting Sort, que é estável.
     * @param array O array de placas a ser ordenado.
     * @param digitIndex O índice do caractere (dígito) a ser usado para a ordenação.
     * @return Um novo array de placas ordenado pelo dígito especificado.
     */
    private static String[] countingSortPorDigito(String[] array, int digitIndex) {
        int n = array.length;
        String[] arrayOrdenado = new String[n];
        int[] contagem = new int[10]; // Para os dígitos de 0 a 9

        // 1. Conta a frequência de cada dígito.
        for (String placa : array) {
            // Character.getNumericValue é uma forma robusta de converter char para int.
            int digito = Character.getNumericValue(placa.charAt(digitIndex));
            contagem[digito]++;
        }

        // 2. Calcula a soma cumulativa para obter as posições finais.
        for (int i = 1; i < 10; i++) {
            contagem[i] += contagem[i - 1];
