            plates = countingSortByDigit(plates, i);
        }

        // Usa String.join para formatar a saída de forma limpa e correta
        System.out.println(String.join(", ", plates));
    }

    /**
     * Ordena o array de placas de forma estável com base no dígito em um índice específico.
     * @param array O array de placas a ser ordenado.
     * @param digitIndex O índice do caractere (dígito) a ser usado para a ordenação.
     * @return Um novo array de placas ordenado.
     */
    private static String[] countingSortByDigit(String[] array, int digitIndex) {
        int n = array.length;
        String[] output = new String[n];
        int[] count = new int[10]; // Para os dígitos de 0 a 9

        // 1. Conta a ocorrência de cada dígito no índice especificado
        for (String plate : array) {
            // Character.getNumericValue é mais seguro e eficiente que Integer.parseInt(char+"")
            int digit = Character.getNumericValue(plate.charAt(digitIndex));
            count[digit]++;
        }

        // 2. Transforma o array de contagem em um array de posições cumulativas
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        // 3. Constrói o array de saída, iterando de trás para frente para garantir estabilidade
        for (int i = n - 1; i >= 0; i--) {
            String plate = array[i];
            int digit = Character.getNumericValue(plate.charAt(digitIndex));

            // Coloca a placa na sua posição correta no array de saída
            output[count[digit] - 1] = plate;

            // Decrementa a contagem para a próxima placa com o mesmo dígito
            count[digit]--;
        }

        return output;
    }
}
