     * @param direita O índice final da sub-sequência atual.
     * @param alvo O número a ser encontrado.
     */
    public static void buscaBinaria(int[] arr, int esquerda, int direita, int alvo) {
        // Condição de parada: se o ponteiro da esquerda ultrapassar o da direita,
        // o elemento não está na sequência.
        if (esquerda > direita) {
            System.out.println("-1");
            return;
        }

        // Calcula o índice do meio. Usar (esquerda + direita) / 2 pode causar overflow
