class TabelaHash {
    private ArrayList<Pair>[] tabela;
    private int M; // Tamanho da tabela

    @SuppressWarnings("unchecked")
    public TabelaHash(int tamanho) {
        this.M = tamanho;
        // A criação de um array de tipos genéricos não é diretamente permitida em Java.
        // Esta é a forma padrão de contornar isso, gerando um warning que pode ser suprimido.
