    // Classe interna para a Árvore Binária de Pesquisa (BST)
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        // Método público para adicionar um valor
        public void add(int value) {
            this.root = addRecursive(this.root, value);
        }

        // Método auxiliar recursivo para inserir um novo nó
        private Node addRecursive(Node current, int value) {
            // Se a subárvore está vazia, cria um novo nó
            if (current == null) {
                return new Node(value);
            }

            // Navega para a esquerda ou direita
            if (value < current.value) {
                current.left = addRecursive(current.left, value);
            } else if (value > current.value) {
                current.right = addRecursive(current.right, value);
            }
            // O valor já existe, não faz nada (conforme premissa do prompt)

            return current;
        }

        // Imprime o caminho até o nó com o valor mínimo
        public void printPathToMin() {
            if (this.root == null) {
                // O prompt garante que a árvore não estará vazia, mas é uma boa prática verificar
