import java.util.Scanner;
import java.util.StringJoiner;

// O nome da classe é Solution, conforme sugerido pelo exemplo de execução do prompt.
public class Solution {

    // Classe interna para representar um nó da árvore.
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    private Node root;

    public Solution() {
        this.root = null;
    }

    /**
     * Adiciona um valor à árvore de forma recursiva.
     * @param current O nó atual na travessia.
     * @param value O valor a ser adicionado.
     * @return O nó raiz da subárvore modificada.
     */
    private Node addRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = addRecursive(current.left, value);
        } else if (value > current.value) {
            current.right = addRecursive(current.right, value);
        }
        // O valor já existe, não faz nada (conforme premissa de não haver elementos repetidos).
        return current;
    }

    /**
     * Método público para iniciar a adição de um valor.
     * @param value O valor a ser adicionado.
     */
    public void add(int value) {
        root = addRecursive(root, value);
    }

    /**
     * Encontra o caminho até o nó de valor mínimo e o imprime na saída padrão.
     * Em uma BST, o valor mínimo é sempre o nó mais à esquerda.
     */
    public void printPathToMin() {
