        if (root == null) {
            return;
        }

        // StringJoiner é uma forma eficiente e limpa de construir strings com delimitadores.
        StringJoiner path = new StringJoiner(" ");
        Node current = root;

        // Percorre a árvore sempre para a esquerda até não haver mais nós à esquerda.
        while (current != null) {
            path.add(String.valueOf(current.value));
            current = current.left;
        }

        System.out.println(path.toString());
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Lê a linha de entrada e a divide em um array de strings.
        String[] inputValues = scanner.nextLine().split(" ");

        Solution bst = new Solution();

        // Itera sobre os valores, converte para inteiro e adiciona à árvore.
