import java.util.Arrays;
import java.util.Scanner;

public class RadixSortSolution {

    /**
     * Ordena um array usando o Radix Sort (LSD - Least Significant Digit).
     * Imprime o estado do array após cada passagem do counting sort.
     *
     * @param array O array de inteiros a ser ordenado.
     * @param d     O número de dígitos que cada inteiro no array possui.
     */
    public static void radixSort(int[] array, int d) {
        // Itera para cada dígito, do menos significativo (LSD) ao mais significativo (MSD)
        int exp = 1; // Representa a casa decimal (1, 10, 100, ...)
        for (int i = 0; i < d; i++) {
            countingSortByDigit(array, exp);
            System.out.println(Arrays.toString(array));
            exp *= 10;
        }
    }

    /**
     * Realiza a ordenação de um array de inteiros com base em um dígito específico,
     * usando o algoritmo Counting Sort. Este método é estável e modifica o array original.
     *
     * @param array O array a ser ordenado.
     * @param exp   O expoente que representa a casa decimal do dígito a ser considerado (1 para unidades, 10 para dezenas, etc.).
     */
    private static void countingSortByDigit(int[] array, int exp) {
        int n = array.length;
        int[] output = new int[n]; // Array de saída temporário
        int[] count = new int[10]; // Array de contagem para os dígitos (0-9)

        // 1. Armazena a contagem de ocorrências de cada dígito
        for (int i = 0; i < n; i++) {
            int digit = (array[i] / exp) % 10;
            count[digit]++;
        }

        // 2. Altera count[i] para que ele contenha a posição final do dígito no array de saída
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        // 3. Constrói o array de saída. A iteração do final para o início
        // garante a estabilidade do algoritmo.
        for (int i = n - 1; i >= 0; i--) {
            int digit = (array[i] / exp) % 10;
            output[count[digit] - 1] = array[i];
            count[digit]--;
        }

        // 4. Copia o array de saída para o array original, para que ele contenha
        // os números ordenados de acordo com o dígito atual.
        System.arraycopy(output, 0, array, 0, n);
