import java.util.Arrays;
import java.util.Scanner;

public class Solution {

    /**
     * Ordena um array de inteiros com base em um dígito específico usando Counting Sort.
     * Este método é estável.
     *
     * @param arr O array a ser ordenado.
     * @param n O tamanho do array.
     * @param exp O expoente que representa o dígito a ser considerado (1 para unidades, 10 para dezenas, etc.).
     */
    private static void countingSortByDigit(int[] arr, int n, int exp) {
        int[] output = new int[n]; // Array de saída
        int[] count = new int[10]; // Array de contagem para os dígitos de 0 a 9

        // 1. Contar a frequência de cada dígito (0-9)
        for (int i = 0; i < n; i++) {
            int digit = (arr[i] / exp) % 10;
            count[digit]++;
        }

        // 2. Modificar o array de contagem para que cada posição contenha a posição final do dígito
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        // 3. Construir o array de saída. Iterar de trás para frente para manter a estabilidade.
        for (int i = n - 1; i >= 0; i--) {
            int digit = (arr[i] / exp) % 10;
            output[count[digit] - 1] = arr[i];
            count[digit]--;
        }

        // 4. Copiar o array de saída ordenado de volta para o array original
        System.arraycopy(output, 0, arr, 0, n);
    }

    /**
     * Realiza a ordenação Radix Sort em um array de inteiros.
     *
     * @param arr O array a ser ordenado.
     * @param d O número de dígitos dos elementos no array.
     */
    private static void radixSort(int[] arr, int d) {
        int exp = 1; // Começa com o dígito menos significativo (unidades)
        for (int i = 0; i < d; i++) {
            countingSortByDigit(arr, arr.length, exp);
            System.out.println(Arrays.toString(arr));
            exp *= 10; // Move para o próximo dígito (dezenas, centenas, etc.)
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Lê a sequência de números
        String[] inputStr = sc.nextLine().split(" ");
        int[] numbers = new int[inputStr.length];
        for (int i = 0; i < numbers.length; i++) {
            numbers[i] = Integer.parseInt(inputStr[i]);
        }

        // Lê a quantidade de dígitos
        int d = sc.nextInt();

        // Executa o Radix Sort
        radixSort(numbers, d);

        sc.close();
    }
}
