/**
 * A classe Solution implementa uma Árvore Binária de Pesquisa (BST) e
 * realiza uma travessia em largura (BFS) nela.
 */
public class Solution {

    // Classe interna para representar um nó da árvore
    private static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    private Node root;

    public Solution() {
        this.root = null;
    }

    /**
     * Adiciona um valor à árvore de forma iterativa.
     * @param value O valor a ser adicionado.
     */
    public void add(int value) {
        if (this.root == null) {
            this.root = new Node(value);
            return;
        }

        Node current = this.root;
        while (true) {
            if (value < current.value) {
                if (current.left == null) {
                    current.left = new Node(value);
                    break;
                }
                current = current.left;
            } else { // value > current.value, pois não há elementos repetidos
                if (current.right == null) {
                    current.right = new Node(value);
                    break;
                }
                current = current.right;
            }
        }
    }

    /**
     * Imprime a travessia em largura (BFS) da árvore.
     */
    public void printBfs() {
        if (root == null) {
            return;
        }

        Queue<Node> queue = new LinkedList<>();
        queue.add(root);

        StringBuilder output = new StringBuilder();

        while (!queue.isEmpty()) {
            Node currentNode = queue.poll();

            if (output.length() > 0) {
                output.append(" ");
            }
            output.append(currentNode.value);

            if (currentNode.left != null) {
                queue.add(currentNode.left);
            }

            if (currentNode.right != null) {
                queue.add(currentNode.right);
            }
        }
        System.out.println(output.toString());
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputValues = scanner.nextLine().split(" ");

        Solution bst = new Solution();

        for (String valStr : inputValues) {
            // Garante que strings vazias (de múltiplos espaços) não causem erro
            if (!valStr.isEmpty()) { 
                bst.add(Integer.parseInt(valStr));
            }
        }

        scanner.close();

        bst.printBfs();
    }
}
