import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

// Classe principal que executa o programa, conforme sugerido pelo prompt "javac Solution.java"
public class Solution {

    // Classe interna para representar um nó da árvore
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            left = null;
            right = null;
        }
    }

    // Classe interna para a Árvore Binária de Pesquisa (BST)
    static class BinarySearchTree {
        Node root;

        BinarySearchTree() {
            this.root = null;
        }

        // Método público para inserir um valor
        public void insert(int value) {
            this.root = insertRec(this.root, value);
        }

        // Método recursivo auxiliar para inserção
        private Node insertRec(Node current, int value) {
            if (current == null) {
                return new Node(value);
            }

            if (value < current.value) {
                current.left = insertRec(current.left, value);
            } else if (value > current.value) {
                current.right = insertRec(current.right, value);
            }
            // O valor já existe, não faz nada (conforme o prompt que assume não haver repetidos)
            return current;
        }

        // Métodos públicos para os três tipos de percurso
        public List<Integer> preOrder() {
            List<Integer> result = new ArrayList<>();
            preOrderRec(root, result);
            return result;
        }

        public List<Integer> inOrder() {
            List<Integer> result = new ArrayList<>();
            inOrderRec(root, result);
            return result;
        }

        public List<Integer> postOrder() {
            List<Integer> result = new ArrayList<>();
            postOrderRec(root, result);
            return result;
        }

        // Métodos recursivos auxiliares para os percursos
        private void preOrderRec(Node node, List<Integer> list) {
            if (node != null) {
                list.add(node.value);
                preOrderRec(node.left, list);
                preOrderRec(node.right, list);
            }
        }

        private void inOrderRec(Node node, List<Integer> list) {
            if (node != null) {
                inOrderRec(node.left, list);
                list.add(node.value);
                inOrderRec(node.right, list);
            }
        }

        private void postOrderRec(Node node, List<Integer> list) {
            if (node != null) {
                postOrderRec(node.left, list);
                postOrderRec(node.right, list);
                list.add(node.value);
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputNumbers = scanner.nextLine().split(" ");

        BinarySearchTree bst = new BinarySearchTree();

        for (String numStr : inputNumbers) {
            if (!numStr.isEmpty()) { // Garante que espaços extras não causem erro
                bst.insert(Integer.parseInt(numStr));
            }
        }
