import java.util.Scanner;

/**
 * O conceito de um "bom pivot" no QuickSort é um elemento que divide a sequência
 * em duas partições de tamanhos aproximadamente iguais. A escolha ideal seria a
 * mediana, que criaria duas partições de tamanho (n-1)/2.
 * 
 * Para determinar qual dos dois candidatos, seq[i] ou seq[j], é a melhor escolha,
 * precisamos calcular quão balanceada seria a partição resultante de cada um.
 * Uma maneira de fazer isso em O(n) é contar, para cada candidato a pivot,
 * quantos elementos na sequência são menores que ele. O número de elementos menores
 * corresponde ao tamanho da partição à esquerda do pivot após o particionamento.
 * 
 * O número ideal de elementos menores é n/2 (divisão inteira). Portanto, o melhor
 * pivot é aquele cujo número de elementos menores está mais próximo de n/2.
 * 
 * Algoritmo:
 * 1. Ler a sequência e os índices i e j.
 * 2. Contar o número de elementos menores que seq[i] (vamos chamar de `menores_i`).
 * 3. Contar o número de elementos menores que seq[j] (vamos chamar de `menores_j`).
 * 4. Calcular a "distância" de cada contagem para o meio do array (n/2):
 *    - dist_i = |menores_i - n/2|
 *    - dist_j = |menores_j - n/2|
 * 5. Comparar as distâncias. Se dist_i <= dist_j, i é a melhor escolha (incluindo o empate).
 *    Caso contrário, j é a melhor escolha.
 */
public class MinhaSolucao {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 1. Leitura e parsing da entrada
        String[] seqStr = sc.nextLine().split(" ");
        String[] indicesStr = sc.nextLine().split(" ");

        int[] seq = new int[seqStr.length];
        for (int k = 0; k < seqStr.length; k++) {
            seq[k] = Integer.parseInt(seqStr[k]);
        }

        int i = Integer.parseInt(indicesStr[0]);
        int j = Integer.parseInt(indicesStr[1]);

        // 2. Obtenção dos valores dos pivots candidatos
        int pivotValorI = seq[i];
        int pivotValorJ = seq[j];

        // 3. Contagem de elementos menores para cada pivot
        int menoresI = 0;
        int menoresJ = 0;
        for (int k = 0; k < seq.length; k++) {
            if (seq[k] < pivotValorI) {
                menoresI++;
            }
            if (seq[k] < pivotValorJ) {
                menoresJ++;
            }
        }
        // Otimização: podemos fazer em um único loop, como feito acima.

        // 4. Cálculo da "distância" ao ponto médio ideal
        int meio = seq.length / 2;
        int distI = Math.abs(menoresI - meio);
        int distJ = Math.abs(menoresJ - meio);

        // 5. Decisão final, com desempate para i
        if (distI <= distJ) {
            System.out.println(i);
        } else {
            System.out.println(j);
        }

        sc.close();
    }
}
