 * 1. Ler a sequência e os índices i e j.
 * 2. Para o candidato seq[i], contar quantos elementos na sequência são menores que ele. Chamemos essa contagem de `menoresI`.
 * 3. Para o candidato seq[j], contar quantos elementos na sequência são menores que ele. Chamemos essa contagem de `menoresJ`.
 * 4. O "ponto de divisão" ideal é o meio da sequência, `meio = n / 2`.
 * 5. Calcular a "distância" de cada candidato ao meio: `distI = |menoresI - meio|` e `distJ = |menoresJ - meio|`.
 * 6. O melhor pivot é aquele com a menor distância. Se as distâncias forem iguais (empate), a regra é escolher `i`.
 * 7. Isso se traduz na condição: se `distI <= distJ`, a resposta é `i`; caso contrário, é `j`.
 * 
 * Esta abordagem tem complexidade O(n) porque requer duas passagens pela sequência,
 * uma para cada candidato, e não viola nenhuma das restrições.
 */
public class MinhaSolucao {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 1. Leitura da sequência de inteiros
        String[] seqStr = sc.nextLine().split(" ");
        int[] seq = new int[seqStr.length];
        for (int k = 0; k < seq.length; k++) {
            seq[k] = Integer.parseInt(seqStr[k]);
        }

        // 2. Leitura dos índices i e j de forma robusta
        String[] indicesStr = sc.nextLine().split(" ");
        int i = Integer.parseInt(indicesStr[0]);
        int j = Integer.parseInt(indicesStr[1]);

        sc.close();

        // 3. Determina e imprime o melhor pivot
        System.out.println(encontrarMelhorPivot(seq, i, j));
    }

    /**
     * Determina o melhor pivot entre os candidatos nos índices i e j.
     * @param seq A sequência de inteiros.
     * @param i O índice do primeiro candidato.
     * @param j O índice do segundo candidato.
     * @return O índice do melhor pivot (i ou j).
     */
    public static int encontrarMelhorPivot(int[] seq, int i, int j) {
        int pivotCandidatoI = seq[i];
        int pivotCandidatoJ = seq[j];

        int menoresI = 0;
        int menoresJ = 0;

        // Contagem de elementos menores que cada candidato (duas passagens O(n))
        for (int k = 0; k < seq.length; k++) {
            if (seq[k] < pivotCandidatoI) {
                menoresI++;
            }
            if (seq[k] < pivotCandidatoJ) {
                menoresJ++;
            }
        }

        // Otimização: podemos fazer em uma única passagem
        // int menoresI = 0;
        // int menoresJ = 0;
        // for (int elemento : seq) {
        //     if (elemento < pivotCandidatoI) menoresI++;
        //     if (elemento < pivotCandidatoJ) menoresJ++;
        // }

        int meio = seq.length / 2;

        // Calcula a distância absoluta da posição final de cada pivot ao meio
        int distI = Math.abs(menoresI - meio);
        int distJ = Math.abs(menoresJ - meio);

        // Compara as distâncias. Em caso de empate (distI == distJ), a condição
        // `distI <= distJ` garante que `i` seja retornado, conforme a regra.
        if (distI <= distJ) {
            return i;
        } else {
            return j;
        }
    }
}
