        }

        private void preOrderRecursive(Node node, ArrayList<Integer> list) {
            if (node != null) {
                list.add(node.value);
                preOrderRecursive(node.left, list);
                preOrderRecursive(node.right, list);
            }
        }

        // Método para encontrar o valor mais próximo de N com complexidade O(h).
        public int findClosestValue(int n) {
            if (root == null) {
                throw new IllegalStateException("A árvore está vazia.");
            }

            Node currentNode = root;
            int closest = root.value;

            while (currentNode != null) {
                // Verifica se o nó atual é mais próximo que o 'closest' atual.
                if (Math.abs(n - currentNode.value) < Math.abs(n - closest)) {
                    closest = currentNode.value;
