                // Se encontramos o valor exato, ele é o mais próximo.
                if (n == currentNode.value) {
                    return n;
                } 
                // Decide para qual sub-árvore navegar, aproveitando a propriedade da BST.
                else if (n < currentNode.value) {
                    currentNode = currentNode.left;
                } else {
                    currentNode = currentNode.right;
                }
            }
            return closest;
        }
