import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;
import java.util.Arrays;

/**
 * Classe que representa um nó da Árvore Binária de Pesquisa (BST).
 */
class Node {
    int value;
    Node left;
    Node right;

    Node(int value) {
        this.value = value;
        left = null;
        right = null;
    }
}

/**
 * Classe que implementa a Árvore Binária de Pesquisa (BST).
 */
class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    /**
     * Insere um valor na árvore.
     */
    public void add(int value) {
        this.root = addRecursive(this.root, value);
    }

    private Node addRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = addRecursive(current.left, value);
        } else if (value > current.value) {
            current.right = addRecursive(current.right, value);
        }
        // valor já existe, não faz nada (conforme premissa de não haver repetidos)
        return current;
    }

    /**
     * Retorna uma lista com o caminhamento em pré-ordem.
     */
    public List<Integer> getPreOrderTraversal() {
        List<Integer> result = new ArrayList<>();
        preOrderRecursive(this.root, result);
        return result;
    }

    private void preOrderRecursive(Node node, List<Integer> list) {
        if (node != null) {
            list.add(node.value);
            preOrderRecursive(node.left, list);
            preOrderRecursive(node.right, list);
        }
    }

    /**
     * Encontra o valor mais próximo de N na árvore com complexidade O(h).
     */
    public int findClosestValue(int n) {
        if (this.root == null) {
            throw new IllegalStateException("A árvore está vazia.");
        }

        Node currentNode = this.root;
        int closest = currentNode.value;

        while (currentNode != null) {
            // Verifica se o nó atual é mais próximo que o 'closest' já encontrado
            if (Math.abs(n - currentNode.value) < Math.abs(n - closest)) {
                closest = currentNode.value;
            }

            // Se encontramos o valor exato, a distância é 0, que é a menor possível.
            if (n == currentNode.value) {
                return n;
            }

            // Decide para qual sub-árvore navegar, usando a propriedade da BST
            if (n < currentNode.value) {
                currentNode = currentNode.left;
            } else {
                currentNode = currentNode.right;
            }
        }
        return closest;
    }
}

