            // Caso base 2: Se o nó não tem filhos, é uma folha, não é interno.
            if (node.left == null && node.right == null) {
                return 0;
            }

            // Passo recursivo: O nó atual é interno. Conte-o (1) e some com os
            // nós internos das subárvores esquerda e direita.
            return 1 + countInternalNodesRecursive(node.left) + countInternalNodesRecursive(node.right);
        }
    }

    public static void main(String[] args) {
