        // Lê a linha inteira de entrada
        String[] inputValues = scanner.nextLine().split(" ");

        BST tree = new BST();

        // Itera sobre os valores lidos e os adiciona à árvore
        for (String valStr : inputValues) {
            if (!valStr.isEmpty()) { // Garante que strings vazias não causem erro
                tree.add(Integer.parseInt(valStr));
            }
        }

        // Imprime o resultado da contagem de nós internos
        System.out.println(tree.countInternalNodes());

        scanner.close();
    }
}
