class Solution {

    /**
     * Função auxiliar para trocar dois elementos em um array.
     * @param arr O array de inteiros.
     * @param i O índice do primeiro elemento.
     * @param j O índice do segundo elemento.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Particiona o array em relação ao primeiro elemento (pivô).
     * Ao final, os elementos menores que o pivô estarão à sua esquerda,
     * e os maiores estarão à sua direita.
     * @param arr O array a ser particionado.
     * @return A estatística de ordem do pivô original.
     */
    public static int partitionAndGetOrderStatistic(int[] arr) {
        if (arr == null || arr.length == 0) {
            return 0;
        }

        int pivotValue = arr[0];
        // 'i' marca a fronteira onde os elementos menores que o pivô terminam.
        // Começamos em 1 porque o pivô está em 0.
        int i = 1; 

        // Percorremos o resto do array com 'j'.
        for (int j = 1; j < arr.length; j++) {
            // Se encontramos um elemento menor que o pivô...
            if (arr[j] < pivotValue) {
                // ...o trocamos para a seção de "menores".
                swap(arr, i, j);
                // E expandimos a fronteira da seção de "menores".
                i++;
            }
        }

        // Ao final do loop, a posição correta do pivô é 'i - 1'.
        // Todos os elementos de arr[1] até arr[i-1] são menores que o pivô.
        // Trocamos o pivô (que ainda está em arr[0]) para sua posição final.
        swap(arr, 0, i - 1);

        // A estatística de ordem é o número de elementos menores + 1.
        // O número de elementos menores é (i - 1).
        // Portanto, a estatística de ordem é (i - 1) + 1 = i.
        return i;
    }

