```java
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.StringJoiner;

public class Solution {

    // Classe interna para representar um nó da árvore
    static class Node {
        int data;
        Node left;
        Node right;

        Node(int data) {
            this.data = data;
            this.left = null;
            this.right = null;
        }
    }

    // Classe para representar a Árvore Binária de Pesquisa (BST)
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        // Método público para inserir um valor
        public void insert(int data) {
            this.root = insertRec(this.root, data);
        }

        // Método recursivo auxiliar para inserção
        private Node insertRec(Node current, int data) {
            if (current == null) {
                return new Node(data);
            }

            if (data < current.data) {
                current.left = insertRec(current.left, data);
            } else if (data > current.data) {
                current.right = insertRec(current.right, data);
            }
            // Elementos repetidos são ignorados, conforme premissa do prompt.

            return current;
        }

        // Método para calcular a altura de um nó
        private int height(Node node) {
            if (node == null) {
                return -1; // Altura de uma árvore vazia é -1
            }
            return 1 + Math.max(height(node.left), height(node.right));
        }

        // Método para calcular o balance de um nó
        private int getBalance(Node node) {
            if (node == null) {
                return 0;
            }
            return height(node.left) - height(node.right);
        }

        // Método para imprimir o encaminhamento em pré-ordem com os balances
        public void printPreOrderBalance() {
            if (root == null) {
                return;
            }
            StringJoiner sj = new StringJoiner(" ");
            preOrderRec(root, sj);
            System.out.println(sj.toString());
        }

        // Método recursivo auxiliar para o encaminhamento em pré-ordem
        private void preOrderRec(Node node, StringJoiner sj) {
            if (node != null) {
                int balance = getBalance(node);
                sj.add(node.data + "," + balance);
                preOrderRec(node.left, sj);
                preOrderRec(node.right, sj);
            }
}
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] numbersStr = scanner.nextLine().split(" ");

        BST tree = new BST();
        for (String numStr : numbersStr) {
            if (!numStr.isEmpty()) {
                tree.insert(Integer.parseInt(numStr));
            }
        }

        tree.printPreOrderBalance();
        scanner.close();
    }
}
