import java.util.Scanner;
import java.util.StringJoiner;

/**
 * Classe que representa uma Árvore Binária de Pesquisa (BST).
 */
class BST {

    /**
     * Classe interna estática para representar um nó da árvore.
     * É uma boa prática encapsular a estrutura do nó dentro da classe da árvore.
     */
    private static class Node {
        int data;
        Node left;
        Node right;

        Node(int data) {
            this.data = data;
            this.left = null;
            this.right = null;
        }
    }

    private Node root;

    public BST() {
        this.root = null;
    }

    /**
     * Insere um novo valor na árvore.
     * @param data O valor a ser inserido.
     */
    public void insert(int data) {
        root = insertRec(root, data);
    }

    /**
     * Método auxiliar recursivo para inserção.
     * @param current O nó atual na recursão.
     * @param data O valor a ser inserido.
     * @return O nó (potencialmente novo) a ser ligado ao seu pai.
     */
    private Node insertRec(Node current, int data) {
        if (current == null) {
            return new Node(data);
        }

        if (data < current.data) {
            current.left = insertRec(current.left, data);
        } else if (data > current.data) {
            current.right = insertRec(current.right, data);
        }
        // Valores duplicados são ignorados, conforme premissa do problema.
        return current;
    }

    /**
     * Calcula a altura de um nó. A altura de um nó nulo é -1.
     * @param node O nó para o qual a altura será calculada.
     * @return A altura do nó.
     */
    private int height(Node node) {
        if (node == null) {
            return -1; // Convenção para facilitar o cálculo no nó pai.
        }
        return 1 + Math.max(height(node.left), height(node.right));
    }

    /**
     * Calcula o balance de um nó.
     * @param node O nó para o qual o balance será calculado.
     * @return O valor do balance.
     */
    private int getBalance(Node node) {
        if (node == null) {
            return 0;
        }
        return height(node.left) - height(node.right);
    }

    /**
     * Gera a string do caminhamento em pré-ordem com os balances.
     * @return Uma string formatada com o resultado.
     */
    public String preOrderWithBalance() {
        StringJoiner joiner = new StringJoiner(" ");
        preOrderRec(root, joiner);
        return joiner.toString();
    }

    /**
     * Método auxiliar recursivo para o caminhamento em pré-ordem.
     * @param node O nó atual na recursão.
     * @param joiner O StringJoiner para construir a string de saída.
     */
    private void preOrderRec(Node node, StringJoiner joiner) {
        if (node != null) {
            int balance = getBalance(node);
            joiner.add(node.data + "," + balance);
            preOrderRec(node.left, joiner);
            preOrderRec(node.right, joiner);
        }
    }
}

