                if (numeros[i] > valorMaximo) {
                    valorMaximo = numeros[i];
                }
            }
        }

        // Cria e preenche o array de frequência.
        // O índice do array corresponde ao número, e o valor no índice é sua frequência.
        int[] frequencia = new int[valorMaximo + 1];
        for (int numero : numeros) {
