```java
import java.util.Scanner;
import java.util.Queue;
import java.util.LinkedList;

// O nome da classe principal deve ser Solution, conforme o exemplo de execução.
public class Solution {

    // Classe interna para representar um nó da árvore.
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    // Classe interna para a Árvore Binária de Pesquisa (BST).
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        // Método para adicionar um novo valor à árvore.
        public void add(int value) {
            this.root = addRecursive(this.root, value);
        }

        // Método auxiliar recursivo para adicionar um nó.
        private Node addRecursive(Node current, int value) {
            if (current == null) {
                return new Node(value);
            }

            if (value < current.value) {
                current.left = addRecursive(current.left, value);
            } else if (value > current.value) {
                current.right = addRecursive(current.right, value);
            }
            // O valor já existe, não faz nada.

            return current;
        }

        // Método para realizar o encaminhamento em largura da direita para a esquerda.
        public void breadthFirstRightToLeft() {
            if (this.root == null) {
                return;
            }

            Queue<Node> queue = new LinkedList<>();
            queue.add(this.root);
            StringBuilder output = new StringBuilder();

            while (!queue.isEmpty()) {
                Node currentNode = queue.poll();

                if (output.length() > 0) {
                    output.append(" ");
                }
                output.append(currentNode.value);

                // A chave para a travessia da direita para a esquerda:
                // Adiciona o filho da direita na fila antes do filho da esquerda.
                if (currentNode.right != null) {
                    queue.add(currentNode.right);
                }
                if (currentNode.left != null) {
                    queue.add(currentNode.left);
                }
            }
            System.out.println(output.toString());
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputNumbers = scanner.nextLine().split(" ");

        BST tree = new BST();
        for (String numStr : inputNumbers) {
            if (!numStr.isEmpty()) {
                tree.add(Integer.parseInt(numStr));
            }
        }
        scanner.close();

        tree.breadthFirstRightToLeft();
    }
}
