import java.util.Scanner;
import java.util.Queue;
import java.util.LinkedList;
import java.util.List;
import java.util.ArrayList;
import java.util.StringJoiner;

// O nome da classe é Solution para corresponder ao comando de exemplo "javac Solution.java"
public class Solution {

    // Classe interna para representar um nó da árvore
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    private Node root;

    public Solution() {
        this.root = null;
    }

    // Método para adicionar um novo valor à BST de forma recursiva
    public void add(int value) {
        this.root = addRecursive(this.root, value);
    }

    private Node addRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = addRecursive(current.left, value);
        } else if (value > current.value) {
            // O prompt assume que não haverá elementos repetidos
            current.right = addRecursive(current.right, value);
        }

        return current;
    }

    /**
     * Realiza o encaminhamento em largura (BFS) na árvore,
     * visitando os nós de cada nível da direita para a esquerda.
     * @return Uma lista de inteiros na ordem de visitação.
     */
    public List<Integer> bfsRightToLeft() {
        List<Integer> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Queue<Node> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            Node currentNode = queue.poll();
            result.add(currentNode.value);

            // Adiciona o filho da direita primeiro para garantir a ordem da direita para a esquerda
            if (currentNode.right != null) {
                queue.add(currentNode.right);
            }
            // Adiciona o filho da esquerda depois
            if (currentNode.left != null) {
                queue.add(currentNode.left);
            }
        }
        return result;
    }

