import java.util.Scanner;

/**
 * A classe principal deve ser nomeada 'Solution' para corresponder ao exemplo de
 * execução fornecido no prompt: "$ javac Solution.java; java Solution".
 */
public class Solution {

    /**
     * Classe interna estática para representar um nó da árvore.
     * É estática para que possa ser instanciada sem uma instância da classe externa Solution.
     */
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    /**
     * Classe interna estática para representar a Árvore de Busca Binária (BST).
     */
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        /**
         * Adiciona um valor à árvore de forma iterativa.
         * @param value O valor a ser adicionado.
         */
        public void add(int value) {
            Node newNode = new Node(value);
            if (root == null) {
                root = newNode;
                return;
            }

            Node current = root;
            while (true) {
                if (value < current.value) {
                    if (current.left == null) {
                        current.left = newNode;
                        return;
                    }
                    current = current.left;
                } else { // value > current.value (sem repetidos)
                    if (current.right == null) {
                        current.right = newNode;
                        return;
                    }
                    current = current.right;
                }
            }
        }

        /**
         * Calcula a altura da árvore.
         * A altura de uma árvore vazia é -1.
         * A altura de uma árvore com um único nó é 0.
         * @return A altura da árvore.
         */
        public int height() {
            return calculateHeight(this.root);
        }

        /**
         * Método auxiliar recursivo para calcular a altura de uma subárvore.
         * @param node O nó raiz da subárvore.
         * @return A altura da subárvore.
         */
        private int calculateHeight(Node node) {
            if (node == null) {
                return -1; // Definição comum para a altura de uma árvore/subárvore vazia.
            }

            int leftHeight = calculateHeight(node.left);
            int rightHeight = calculateHeight(node.right);

            // A altura é 1 + a altura da maior subárvore.
            return 1 + Math.max(leftHeight, rightHeight);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Lê a linha inteira de entrada e a divide em strings de números.
        String[] inputNumbers = scanner.nextLine().split(" ");
        scanner.close();

        BST tree = new BST();

        // Itera sobre as strings, converte para inteiros e adiciona à árvore.
        for (String numberStr : inputNumbers) {
            // Garante que strings vazias (por exemplo, de múltiplos espaços) não causem erro.
            if (!numberStr.isEmpty()) {
                tree.add(Integer.parseInt(numberStr));
            }
        }

        // Imprime a altura da árvore resultante.
        System.out.println(tree.height());
    }
}
