/**
 * Classe que representa a Árvore Binária de Busca (BST).
 */
class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    /**
     * Adiciona um novo valor à árvore.
     * @param value O valor a ser adicionado.
     */
    public void add(int value) {
        root = addRecursive(root, value);
    }

    /**
     * Método auxiliar recursivo para adicionar um nó.
     * @param current O nó atual na recursão.
     * @param value O valor a ser adicionado.
     * @return O nó raiz da subárvore modificada.
     */
    private Node addRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = addRecursive(current.left, value);
        } else if (value > current.value) {
            current.right = addRecursive(current.right, value);
        }
        // O valor já existe, não faz nada (conforme premissa do prompt).

        return current;
    }

    /**
     * Calcula a altura da árvore.
     * A altura é definida como o número de arestas no caminho mais longo da raiz até uma folha.
     * A altura de uma árvore vazia é -1.
     * @return A altura da árvore.
     */
    public int height() {
        return heightRecursive(root);
    }

    /**
     * Método auxiliar recursivo para calcular a altura.
     * @param node O nó atual na recursão.
     * @return A altura da subárvore com raiz no nó fornecido.
     */
    private int heightRecursive(Node node) {
        if (node == null) {
            return -1;
        }

        int leftHeight = heightRecursive(node.left);
        int rightHeight = heightRecursive(node.right);

        return 1 + Math.max(leftHeight, rightHeight);
    }
}

